using System;
using System.Collections.Generic;
using System.DirectoryServices.Protocols;
using System.Net;
using System.Security.Principal;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace CloudInfra.Kerberos.Delegation
{
    public enum DelegationMode
    {
        None = 0,
        Constrained = 1,
        ResourceBased = 2,
        Unconstrained = 3
    }

    public class DelegationPolicy
    {
        public string ServicePrincipalName { get; set; }
        public DelegationMode Mode { get; set; }
        public List<string> AllowedTargetSpns { get; set; } = new List<string>();
        public bool ProtocolTransitionEnabled { get; set; }
        public TimeSpan TicketLifetime { get; set; } = TimeSpan.FromHours(8);
    }

    public class KerberosServiceAccountManager
    {
        private readonly ILogger<KerberosServiceAccountManager> _logger;
        private readonly LdapConnection _ldapConnection;
        private readonly Dictionary<string, DelegationPolicy> _policyCache;
        private readonly object _cacheLock = new object();

        public KerberosServiceAccountManager(ILogger<KerberosServiceAccountManager> logger, LdapConnection ldapConnection)
        {
            _logger = logger;
            _ldapConnection = ldapConnection;
            _policyCache = new Dictionary<string, DelegationPolicy>(StringComparer.OrdinalIgnoreCase);
        }

        public DelegationPolicy ResolveDelegationPolicy(string servicePrincipalName, string podServiceAccount)
        {
            if (string.IsNullOrWhiteSpace(servicePrincipalName))
                throw new ArgumentException("Service principal name must be provided", nameof(servicePrincipalName));

            lock (_cacheLock)
            {
                if (_policyCache.TryGetValue(servicePrincipalName, out var cached))
                    return cached;
            }

            var policy = FetchPolicyFromDirectory(servicePrincipalName, podServiceAccount);
            lock (_cacheLock)
            {
                _policyCache[servicePrincipalName] = policy;
            }
            return policy;
        }

        private DelegationPolicy FetchPolicyFromDirectory(string spn, string podServiceAccount)
        {
            var searchRequest = new SearchRequest(
                "DC=corp,DC=internal",
                $"(servicePrincipalName={EscapeLdapFilter(spn)})",
                SearchScope.Subtree,
                "msDS-AllowedToDelegateTo",
                "userAccountControl",
                "msDS-AllowedToActOnBehalfOfOtherIdentity"
            );

            var response = (SearchResponse)_ldapConnection.SendRequest(searchRequest);
            if (response.Entries.Count == 0)
                return new DelegationPolicy { ServicePrincipalName = spn, Mode = DelegationMode.None };

            var entry = response.Entries[0];
            var uac = Convert.ToInt32(entry.Attributes["userAccountControl"][0]);
            var policy = new DelegationPolicy { ServicePrincipalName = spn };

            policy.Mode = ClassifyDelegationMode(uac, entry);

            if (entry.Attributes.Contains("msDS-AllowedToDelegateTo"))
            {
                foreach (string targetSpn in entry.Attributes["msDS-AllowedToDelegateTo"])
                    policy.AllowedTargetSpns.Add(targetSpn);
            }

            policy.ProtocolTransitionEnabled = IsProtocolTransitionEnabled(uac);
            return policy;
        }

        private DelegationMode ClassifyDelegationMode(int userAccountControl, SearchResultEntry entry)
        {
            const int TRUSTED_FOR_DELEGATION = 0x80000;
            const int TRUSTED_TO_AUTH_FOR_DELEGATION = 0x1000000;

            if ((userAccountControl & TRUSTED_FOR_DELEGATION) != 0)
                return DelegationMode.Unconstrained;
            if ((userAccountControl & TRUSTED_TO_AUTH_FOR_DELEGATION) != 0)
                return DelegationMode.Constrained;
            if (entry.Attributes.Contains("msDS-AllowedToActOnBehalfOfOtherIdentity"))
                return DelegationMode.ResourceBased;
            return DelegationMode.None;
        }

        private bool IsProtocolTransitionEnabled(int uac)
        {
            const int TRUSTED_TO_AUTH_FOR_DELEGATION = 0x1000000;
            return (uac & TRUSTED_TO_AUTH_FOR_DELEGATION) != 0;
        }

        private string EscapeLdapFilter(string input)
        {
            if (input == null)
                return string.Empty;
            return input.Replace("\\", "\\5c").Replace("*", "\\2a")
                       .Replace("(", "\\28").Replace(")", "\\29")
                       .Replace("\0", "\\00");
        }
    }

    public class DelegationEnforcementMiddleware
    {
        private readonly KerberosServiceAccountManager _manager;
        private readonly ILogger<DelegationEnforcementMiddleware> _logger;
        private readonly HashSet<string> _trustedNamespaces;

        public DelegationEnforcementMiddleware(
            KerberosServiceAccountManager manager,
            ILogger<DelegationEnforcementMiddleware> logger,
            IEnumerable<string> trustedNamespaces)
        {
            _manager = manager;
            _logger = logger;
            _trustedNamespaces = new HashSet<string>(trustedNamespaces, StringComparer.OrdinalIgnoreCase);
        }

        public async Task<DelegationDecision> EvaluateRequest(
            string requestorSpn,
            string targetSpn,
            string podNamespace,
            string podServiceAccount,
            WindowsIdentity impersonatedIdentity)
        {
            if (string.IsNullOrWhiteSpace(requestorSpn) || string.IsNullOrWhiteSpace(targetSpn))
            {
                _logger.LogWarning("Delegation denied: missing requestor or target SPN");
                return DelegationDecision.Deny("Invalid delegation request parameters");
            }

            var policy = _manager.ResolveDelegationPolicy(requestorSpn, podServiceAccount);

            if (policy.Mode == DelegationMode.None)
            {
                _logger.LogWarning("Delegation denied: no delegation configured for {Spn}", requestorSpn);
                return DelegationDecision.Deny("No delegation configured");
            }

            if (!ValidateNamespaceBinding(podNamespace, requestorSpn))
            {
                _logger.LogWarning("Namespace binding violation for {Spn} in {Ns}", requestorSpn, podNamespace);
                return DelegationDecision.Deny("Namespace binding violation");
            }

            return EvaluateDelegationChain(policy, targetSpn, impersonatedIdentity);
        }

        private DelegationDecision EvaluateDelegationChain(
            DelegationPolicy policy,
            string targetSpn,
            WindowsIdentity impersonatedIdentity)
        {
            switch (policy.Mode)
            {
                case DelegationMode.Constrained:
                    return EvaluateConstrainedDelegation(policy, targetSpn);

                case DelegationMode.ResourceBased:
                    return EvaluateResourceBasedDelegation(policy, targetSpn);

                case DelegationMode.Unconstrained:
                    _logger.LogCritical("Unconstrained delegation BLOCKED for {Spn} - policy violation",
                        policy.ServicePrincipalName);
                    return DelegationDecision.Deny("Unconstrained delegation is prohibited by security policy");

                default:
                    return DelegationDecision.Deny("Unknown delegation mode");
            }
        }

        private DelegationDecision EvaluateConstrainedDelegation(DelegationPolicy policy, string targetSpn)
        {
            var normalizedTarget = NormalizeSpn(targetSpn);
            foreach (var allowed in policy.AllowedTargetSpns)
            {
                if (NormalizeSpn(allowed).Equals(normalizedTarget, StringComparison.OrdinalIgnoreCase))
                    return DelegationDecision.Allow(policy.Mode, targetSpn);
            }

            return DelegationDecision.Deny($"Target {targetSpn} not in allowed list");
        }

        private DelegationDecision EvaluateResourceBasedDelegation(DelegationPolicy policy, string targetSpn)
        {
            var normalizedTarget = NormalizeSpn(targetSpn);
            foreach (var allowed in policy.AllowedTargetSpns)
            {
                if (NormalizeSpn(allowed).Equals(normalizedTarget, StringComparison.OrdinalIgnoreCase))
                    return DelegationDecision.Allow(policy.Mode, targetSpn);
            }
            return DelegationDecision.Deny($"RBCD: Target {targetSpn} not authorized");
        }

        private bool ValidateNamespaceBinding(string podNamespace, string spn)
        {
            if (string.IsNullOrWhiteSpace(podNamespace))
                return false;
            return _trustedNamespaces.Contains(podNamespace);
        }

        private string NormalizeSpn(string spn)
        {
            if (string.IsNullOrEmpty(spn))
                return string.Empty;

            var parts = spn.Split('/');
            if (parts.Length >= 2)
            {
                var host = parts[1].Split(':')[0].ToLowerInvariant();
                return $"{parts[0]}/{host}";
            }
            return spn.ToLowerInvariant();
        }
    }

    public class DelegationDecision
    {
        public bool Allowed { get; private set; }
        public string Reason { get; private set; }
        public DelegationMode Mode { get; private set; }
        public string TargetSpn { get; private set; }

        public static DelegationDecision Allow(DelegationMode mode, string targetSpn)
            => new DelegationDecision { Allowed = true, Mode = mode, TargetSpn = targetSpn, Reason = "Permitted" };

        public static DelegationDecision Deny(string reason)
            => new DelegationDecision { Allowed = false, Reason = reason };
    }
}
